  'rdpHub.fields.security': "حماية",
  'rdpHub.fields.username': "اسم المستخدم",
  'rdpHub.guacdUnreachable': "لا يمكن الوصول إلى guacd",
  'rdpHub.guacdUnreachable.lead': "لا يمكن لـ AppEndO فتح أجهزة سطح المكتب البعيدة حتى يتم تشغيل Apache Guacamole guacd على الجهاز الذي يستضيف عملية AppEndO هذه. نقطة النهاية التي تم التحقيق فيها: {endpoint}. لا يحتاج جهاز الكمبيوتر الشخصي الذي يعمل بنظام التشغيل Windows والذي تريد الاتصال به عن بعد إلى guacd - فقط تمكين سطح المكتب البعيد (المنفذ 3389).",
  'rdpHub.guacdUnreachable.linux.commandDebian': "سودو التحديث المناسب\nsudo apt install -y guacd\nتمكين سودو systemctl - الآن guacd\nSudo systemctl Status guacd --no-pager",
  'rdpHub.guacdUnreachable.linux.commandDocker': "تشغيل عامل الميناء -d - اسم guacd - إعادة التشغيل ما لم يتوقف -p 4822:4822 guacamole/guacd",
  'rdpHub.guacdUnreachable.linux.commandDockerStart': "تشغيل:\ndocker start guacd",
  'rdpHub.guacdUnreachable.linux.commandVerify': "ss -lnt | جريب 4822\n# أو: nc -zv 127.0.0.1 4822",
  'rdpHub.guacdUnreachable.linux.debian': "الخيار ب – حزمة Ubuntu / Debian (بدون Docker):",
  'rdpHub.guacdUnreachable.linux.docker': "الخيار أ – Docker (أي توزيعة). قم بإنشاء الحاوية مرة واحدة؛ تعمل الأحذية اللاحقة على استمرار تشغيله بسبب --restart ما لم يتم إيقافه:",
  'rdpHub.guacdUnreachable.linux.dockerStart': "إذا كانت الحاوية موجودة بالفعل:",
  'rdpHub.guacdUnreachable.linux.env': "إذا كانت نقطة النهاية التي تم فحصها ليست 127.0.0.1:4822، فقم بتعيين GUACD_HOST وGUACD_PORT في AppEndO .env للمطابقة، ثم أعد تشغيل AppEndO.",
  'rdpHub.guacdUnreachable.linux.intro': "اتبع هذا القسم عند تثبيت AppEndO على Linux. قم بتثبيت guacd على مضيف AppEndO هذا فقط.",
  'rdpHub.guacdUnreachable.linux.other': "Fedora وRHEL وSUSE والتوزيعات الأخرى: تفضل Docker. في حالة وجود حزمة توزيعة، عادةً ما يطلق عليها اسم guacd أو guacamole-server — قم بتمكين هذه الخدمة وبدء تشغيلها، ثم تحقق من المنفذ 4822 كما هو مذكور أعلاه.",
  'rdpHub.guacdUnreachable.linux.title': "مضيف لينكس",
  'rdpHub.guacdUnreachable.linux.verify': "تأكد من أن guacd يستمع على المنفذ الذي تم فحصه:",
  'rdpHub.guacdUnreachable.refresh': "بعد استماع guacd، قم بتحديث هذه الصفحة. يتم مسح التحذير عندما يتمكن AppEndO من الوصول إلى نقطة النهاية.",
  'rdpHub.guacdUnreachable.windows.commandRun': "تشغيل عامل الميناء -d - اسم guacd - إعادة التشغيل ما لم يتوقف -p 4822:4822 guacamole/guacd",
  'rdpHub.guacdUnreachable.windows.commandStart': "تشغيل:\ndocker start guacd",
  'rdpHub.guacdUnreachable.windows.commandVerify': "التحقق:\ndocker ps --filter name=guacd\nTest-NetConnection 127.0.0.1 -Port 4822",
  'rdpHub.guacdUnreachable.windows.commandWsl': "سودو التحديث المناسب\nsudo apt install -y guacd\nبدء خدمة Sudo guacd",
  'rdpHub.guacdUnreachable.windows.env': "إذا كانت نقطة النهاية التي تم فحصها ليست 127.0.0.1:4822، فقم بتعيين GUACD_HOST وGUACD_PORT في AppEndO .env على العنوان الذي يستمع إليه Docker أو WSL بالفعل، ثم أعد تشغيل AppEndO.",
  'rdpHub.guacdUnreachable.windows.intro': "اتبع هذا القسم عند تثبيت AppEndO على نظام التشغيل Windows. لا يقوم Apache بشحن مثبت Windows guacd الأصلي — قم بتشغيل guacd في Docker على مضيف AppEndO هذا.",
  'rdpHub.guacdUnreachable.windows.step1': "1. قم بتثبيت Docker Desktop لنظام التشغيل Windows وابدأ تشغيله. قم بتمكين الواجهة الخلفية لـ WSL 2 أثناء الإعداد، ثم انتظر حتى يبلغ Docker عن تشغيله.",
  'rdpHub.guacdUnreachable.windows.step2': "2. افتح PowerShell وقم بإنشاء الحاوية مرة واحدة. ينشر هذا guacd على TCP 4822 على هذا الجهاز:",
  'rdpHub.guacdUnreachable.windows.step3': "3. إذا كانت هذه الحاوية موجودة بالفعل، فابدأ تشغيلها بدلاً من إنشائها مرة أخرى:",
  'rdpHub.guacdUnreachable.windows.step4': "4. تأكد من تشغيل الحاوية وأن المنفذ 4822 يقبل الاتصالات:",
  'rdpHub.guacdUnreachable.windows.title': "مضيف ويندوز",
  'rdpHub.guacdUnreachable.windows.wsl': "إذا لم تتمكن من استخدام Docker Desktop، فقم بتثبيت guacd داخل WSL (Ubuntu) على نفس جهاز الكمبيوتر واستمر في تشغيل الخدمة حتى يتمكن Windows من الوصول إلى 127.0.0.1:4822:",
  'rdpHub.keepSecret': "اتركه فارغًا للحفاظ على السر المخزن.",
